// Local Tauri mobile plugin: Android Keystore custody for the identity vault's
// device key (`DeviceKeyStore.kt`).
//
// Wired in by `gen/android/settings.gradle` (`include(":edet-keystore")`) and
// `gen/android/app/build.gradle.kts` (`implementation(project(":edet-keystore"))`),
// both of which are TRACKED for that reason: `tauri android init` regenerates
// everything in `gen/android` that carries its AUTOGENERATED banner, and those
// two do not, so a regeneration that dropped them would take Android custody
// with it and leave every gate green. `src-tauri/android-custody/settings.gradle`
// includes it as well: that is the root the instrumented test runs from, on a
// checkout that has not built the app.
plugins {
    id("com.android.library")
    id("org.jetbrains.kotlin.android")
}

android {
    namespace = "org.edet.client.keystore"
    compileSdk = 34

    defaultConfig {
        // Android Keystore's AES-GCM `KeyGenParameterSpec` API needs API 23+.
        minSdk = 23
        consumerProguardFiles("consumer-rules.pro")
        testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"
    }

    // Java 17, the LTS the Android toolchain is built around: AGP 8.11 needs a
    // JDK 17+ to run at all, and `nix develop .#android` supplies JDK 21, which
    // warns on every `source/target 8` compile that support for it is
    // deprecated and going away.
    //
    // **This has to move together with `app/build.gradle.kts`, and it cannot
    // move alone.** The app module consumes this one, and a consumer at a lower
    // target cannot read a library at a higher one — Kotlin refuses with
    // "Cannot inline bytecode built with JVM target 17 into bytecode that is
    // being built with JVM target 1.8". The other direction is fine, which is
    // why `:tauri-android` and `:tauri-plugin-shell` staying at 8 costs
    // nothing: we consume them, they do not consume us.
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
    kotlinOptions {
        jvmTarget = "17"
    }
}

dependencies {
    implementation("androidx.core:core-ktx:1.12.0")
    // Provides app.tauri.plugin.{Plugin,Invoke,JSObject} and the
    // app.tauri.annotation.{TauriPlugin,Command} annotations every Tauri
    // Android plugin implements against.
    implementation(project(":tauri-android"))

    // The instrumented test (`src/androidTest`), which is the only thing that
    // RUNS this module's custody: a Keystore key and a file under
    // `noBackupFilesDir` exist on a device or an emulator and nowhere else.
    androidTestImplementation("androidx.test.ext:junit:1.1.5")
    androidTestImplementation("androidx.test:runner:1.5.2")
    androidTestImplementation("androidx.test:core:1.5.0")
}
